    TORCH_CHECK(weight.dim() == 4, "weight must be OIHW");

    int64_t N = input.size(0);
    int64_t C_in = input.size(1);
    int64_t H = input.size(2);
    int64_t W = input.size(3);

    int64_t C_out = weight.size(0);
    int64_t K_h = weight.size(2);
    int64_t K_w = weight.size(3);

    TORCH_CHECK(weight.size(1) == C_in, "C_in mismatch between input and weight");

    int64_t H_out = (H + 2 * pad_h - K_h) / stride_h + 1;
    int64_t W_out = (W + 2 * pad_w - K_w) / stride_w + 1;
    TORCH_CHECK(H_out >= 0 && W_out >= 0, "Computed output size is negative");

    auto out = torch::empty({N, C_out, H_out, W_out}, input.options());

    dim3 block(16, 16);
    dim3 grid((W_out + block.x - 1) / block.x,
              (H_out + block.y - 1) / block.y,
              N * C_out);

    const uint16_t* in_ptr = reinterpret_cast<const uint16_t*>(input.data_ptr<at::BFloat16>());
    const uint16_t* w_ptr  = reinterpret_cast<const uint16_t*>(weight.data_ptr<at::BFloat16>());
    uint16_t* out_ptr      = reinterpret_cast<uint16_t*>(out.data_ptr<at::BFloat16>());

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();

    conv2d_bf16_kernel<<<grid, block, 0, stream>>>(
        in_ptr, w_ptr, out_ptr,
        (int)N, (int)C_in, (int)H, (int)W,
        (int)C_out, (int)K_h, (int)K_w,
        stride_h, stride_w,
        pad_h, pad_w,
        (int)H_out, (int)W_out
    );
    C10_CUDA_KERNEL_LAUNCH_CHECK();

    return out;
}

